    # Start with the simplest case: {1, 2, ..., 2n}
    S = list(range(1, 2*n + 1))

    def has_required_partitions(S, n):
        for m in range(2, n+1):
            found_partition = False
            # Try to partition S into two subsets with equal sum
            for i in range(1 << len(S)):
                subset1, subset2 = [], []
