                    if i & (1 << j):
                        subset1.append(S[j])
                    else:
                        subset2.append(S[j])
                if len(subset1) == m and sum(subset1) == sum(subset2):
                    found_partition = True
                    break
            if not found_partition:
                return False
        return True

    if has_required_partitions(S, n):
        return S
    else:
        return None

